use super::*;

/// The order to make the calls in, with the one sentence that opens each.
pub fn call_order(cases: &[NegotiationCase]) -> Vec<String> {
    cases
        .iter()
        .map(|c| match c.ask {
            Ask::FeeWaiver => format!("{}: \"I saw a fee on my last statement and I'd like to ask for it to be waived.\"", c.institution),
            Ask::HardshipPlan => format!("{}: \"I want to stay current and I'm not going to be able to at this rate. What hardship options do you have?\"", c.institution),
            Ask::RateReduction => format!("{}: \"I've been a customer a while and I'm looking at my rate. What can you do?\"", c.institution),
        })
        .collect()
}
